var (
	foldOnce  sync.Once
	foldTable map[rune]rune
)

func Rune(r rune) rune {
	foldOnce.Do(func() {
		trad := []rune(foldTrad)
		simp := []rune(foldSimp)
		foldTable = make(map[rune]rune, len(trad))
		for i, t := range trad {
			if i < len(simp) {
				foldTable[t] = simp[i]
			}
		}
	})
	if s, ok := foldTable[r]; ok {
		return s
	}
	return r
}

// foldCJK folds every Traditional rune in s to its Simplified form and leaves
// everything else — Latin, Cyrillic, Hiragana, Katakana, Hangul — untouched.
func String(s string) string {
	var changed bool
	runes := []rune(s)
	for i, r := range runes {
		if f := Rune(r); f != r {
			runes[i] = f
			changed = true
		}
	}
	if !changed {
		return s
	}
	return string(runes)
}

// IsCJK reports whether r is a Han, Hiragana, Katakana or Hangul rune — the
// scripts this package folds, and the ones written without spaces between words.
func IsCJK(r rune) bool {
	return unicode.Is(unicode.Han, r) || unicode.Is(unicode.Hiragana, r) ||
		unicode.Is(unicode.Katakana, r) || unicode.Is(unicode.Hangul, r) ||
		isKanaMark(r)
}

// isKanaMark covers the two marks Japanese writes inside a word that no script
// table claims: the prolonged sound mark and its halfwidth twin. The iteration
// marks look like the same case and are not — Go files 々 and 〻 under Han and
// ヽヾゝゞ under their kana scripts, so adding them here changed nothing and
// they are left to the tables that already have them.
//
// ー is not decoration: it appears in most loanwords — サーバー, エラー,
// ステージング — and leaving it out of the script test split every such word
// into two runs. The bigrams then came out of the pieces, and since the token
// was no longer a single CJK run the query kept the whole word as a term the
// index can never hold: searching ステージング for a session that says
// ステージング answered on the close tier instead of the exact one (#1319).
func isKanaMark(r rune) bool {
	switch r {
	case 0x30FC, // ー prolonged sound mark
		0xFF70, // ｰ its halfwidth form
		0xFF9E, // ﾞ halfwidth voiced sound mark, written after the kana it voices
		0xFF9F, // ﾟ halfwidth semi-voiced
		0x3006: // 〆, as in 〆切
		return true
	}
	return false
}

// HasCJK reports whether s contains any Han, Hiragana, Katakana or Hangul
// rune, i.e. whether folding could make any difference to it.
func HasCJK(s string) bool {
	for _, r := range s {
		if IsCJK(r) {
			return true
		}
	}
	return false
}

// CountCJK is HasCJK by the number: how many of s's runes are written in those
// scripts. A caller deciding whether a line is prose in one of them needs the
// share, not the presence — a JSON blob with Chinese values has both.
//
// A mark counts only where there is a word for it to be part of: "ーーーー" is
// a rule drawn with dashes, and counting it as four Japanese runes made the
// digest read a table border as prose.
func CountCJK(s string) int {
	n, words := 0, 0
	for _, r := range s {
		if !IsCJK(r) {
			continue
		}
		n++
		if !isKanaMark(r) {
			words++
		}
	}
	if words == 0 {
		return 0
	}
	return n
}

// Bigrams emits the bigram set for every CJK run in s.
//
// Bigrams keep the script they were written in. Folding happens where postings
// keys are built (indexKeys and queryKeys), not here, so the query-time
// function-word filter still sees the runes the user actually typed: 係 folds
// to 系, which is a content character in 系統 and 關係, so a filter applied
// after folding could not tell the two apart.
func Bigrams(s string) []string {
	// The index hands this the whole message body, so a transcript with no CJK in
	// it would otherwise decode every rune and run all four unicode.Is searches
	// to build nothing. A CJK rune is never a single UTF-8 byte, so one byte scan
	// answers the question before any decoding starts.
	ascii := true
	for i := 0; i < len(s); i++ {
		if s[i] >= utf8.RuneSelf {
			ascii = false
			break
		}
	}
	if ascii {
		return nil
	}

	var out []string
	seen := map[string]bool{}
	var run []rune
	flush := func() {
		// A run of nothing but marks is not a word: "ー" alone would take a
		// posting and match nothing anyone means to search for.
		allMarks := len(run) > 0
		for _, r := range run {
			if !isKanaMark(r) {
				allMarks = false
				break
			}
		}
		if allMarks {
			run = run[:0]
			return
		}
		switch {
		case len(run) == 1:
			t := string(run)
			if !seen[t] {
				seen[t] = true
				out = append(out, t)
			}
		case len(run) >= 2:
			for i := 0; i+1 < len(run); i++ {
				t := string(run[i : i+2])
				if !seen[t] {
					seen[t] = true
					out = append(out, t)
				}
			}
		}
		run = run[:0]
	}
	for _, r := range s {
		if IsCJK(r) {
			run = append(run, r)
			continue
		}
		flush()
	}
	flush()
	return out
}
